/* AIVIC_FUNCTION_BUNDLE_END owner=sendConfirmationEmailsOnReporting */

/* AIVIC_FUNCTION_BUNDLE_START owner=validateSenderEmailFormat exports=validateSenderEmailFormat */
const __aivicBundle_46_validateSenderEmailFormat = (() => {
  function validateSenderEmailFormat(email: string): EmailValidationResult {
    // Basic type check
    if (typeof email !== 'string') {
      return {
        isValid: false,
        error: 'invalid',
      };
    }
  
    const trimmedEmail = email.trim();
  
    // Check for empty string
    if (trimmedEmail.length === 0) {
      return {
        isValid: false,
        error: 'format',
      };
    }
  
    // Check for spaces in email
    if (/\s/.test(trimmedEmail)) {
      return {
        isValid: false,
        error: 'invalid',
      };
    }
  
    // Split by @ to validate structure
    const parts = trimmedEmail.split('@');
  
    // Must have exactly one @ symbol
    if (parts.length !== 2) {
      return {
        isValid: false,
        error: 'format',
      };
    }
  
    const [localPart, domainPart] = parts;
  
    // Local part (before @) must not be empty
    if (localPart.length === 0) {
      return {
        isValid: false,
        error: 'email',
      };
    }
  
    // Domain part (after @) must not be empty
    if (domainPart.length === 0) {
      return {
        isValid: false,
        error: 'email',
      };
    }
  
    // Domain must contain at least one dot and not start with dot
    if (!domainPart.includes('.') || domainPart.startsWith('.')) {
      return {
        isValid: false,
        error: 'format',
      };
    }
  
    // Domain must not have consecutive dots or end with dot
    if (domainPart.includes('..') || domainPart.endsWith('.')) {
      return {
        isValid: false,
        error: 'format',
      };
    }
  
    // Local part must not have consecutive dots or start/end with dot
    if (localPart.includes('..') || localPart.startsWith('.') || localPart.endsWith('.')) {
      return {
        isValid: false,
        error: 'format',
      };
    }
  
    // Check for consecutive @ symbols (already caught by split, but be explicit)
    if (trimmedEmail.includes('@@')) {
      return {
        isValid: false,
        error: 'format',
      };
    }
  
    // Valid email format
    return {
      isValid: true,
    };
  }
  return { validateSenderEmailFormat };
})();
export const validateSenderEmailFormat = __aivicBundle_46_validateSenderEmailFormat.validateSenderEmailFormat;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateSenderEmailFormat */

