const __aivicBundle_49_filterCompleteReports = (() => {
  function filterCompleteReports(
    reports: Array<{
      yesterday_accomplishment?: string;
      today_plan?: string;
      issue_held?: string;
      [key: string]: any;
    }>
  ): Array<{
    yesterday_accomplishment: string;
    today_plan: string;
    issue_held: string;
    [key: string]: any;
  }> {
    return reports
      .filter((report) => {
        const yesterday = report.yesterday_accomplishment;
        const today = report.today_plan;
        const issue = report.issue_held;
  
        const isYesterdayValid =
          yesterday !== null &&
          yesterday !== undefined &&
          yesterday !== "";
        const isTodayValid =
          today !== null &&
          today !== undefined &&
          today !== "";
        const isIssueValid =
          issue !== null &&
          issue !== undefined &&
          issue !== "";
  
        return isYesterdayValid && isTodayValid && isIssueValid;
      })
      .map((report) => ({
        ...report,
        yesterday_accomplishment: report.yesterday_accomplishment!,
        today_plan: report.today_plan!,
        issue_held: report.issue_held!,
      }));
  }
  return { filterCompleteReports };
})();
