/* AIVIC_FUNCTION_BUNDLE_START owner=sendReminderEmail exports=sendReminderEmail */
const __aivicBundle_156_sendReminderEmail = (() => {
  async function sendReminderEmail(
    recipientEmail: string,
    subject: string,
    body: string,
    emailService: { send: (to: string, subject: string, body: string) => Promise<{ success: boolean; messageId: string }> }
  ): Promise<{ sent: boolean; messageId: string; sentAt: Date; error?: string }> {
    const sentAt = new Date();
  
    // Validate email format
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(recipientEmail)) {
      return {
        sent: false,
        messageId: '',
        sentAt,
        error: 'Invalid email format'
      };
    }
  
    // Validate required fields
    if (!subject || !body) {
      return {
        sent: false,
        messageId: '',
        sentAt,
        error: 'Subject and body are required'
      };
    }
  
    try {
      const result = await emailService.send(recipientEmail, subject, body);
  
      if (result.success) {
        return {
          sent: true,
          messageId: result.messageId,
          sentAt
        };
      } else {
        return {
          sent: false,
          messageId: '',
          sentAt,
          error: 'Email service failed to send'
        };
      }
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Unknown error occurred';
      return {
        sent: false,
        messageId: '',
        sentAt,
        error: errorMessage
      };
    }
  }
  return { sendReminderEmail };
})();
